SET NOCOUNT ON;
DECLARE @Out nvarchar(max)=(SELECT CAST(1 AS bit) AS ok,'TEST' AS folder,
 (SELECT t.name AS [table] FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE s.name='TEST' ORDER BY t.name FOR JSON PATH) AS tables,
 (SELECT t.name AS [table],c.name AS [column],TYPE_NAME(c.system_type_id) AS [type],c.max_length,c.precision,c.scale,c.is_nullable,c.is_identity,c.is_computed,c.default_object_id
 FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id
 WHERE s.name='TEST' AND (t.name IN ('ITMMASTER','ITMCATEG','ITMFACILIT','ITMSALES','ITMBPS','ATEXTRA','BPARTNER','BPSUPPLIER','BPADDRESS','CONTACT','CONTACTCRM','TABUNIT','TABCOEFF','TABVAT','TABVAC','TABVACITM','TABPAYTERM','GACCCODE','ATABZON','ATABIND','ATABTAB','ATABFIC') OR c.name LIKE '%ITMREF%' OR c.name LIKE '%BPSNUM%' OR c.name LIKE '%BPRNUM%' OR c.name LIKE '%BPANUM%' OR c.name LIKE '%BPR_0' OR c.name LIKE '%BPS_0') ORDER BY t.name,c.column_id FOR JSON PATH) AS columns,
 (SELECT t.name AS [table],COALESCE(HAS_PERMS_BY_NAME('TEST.'+t.name,'OBJECT','SELECT'),0) AS can_select,COALESCE(HAS_PERMS_BY_NAME('TEST.'+t.name,'OBJECT','UPDATE'),0) AS can_update,COALESCE(HAS_PERMS_BY_NAME('TEST.'+t.name,'OBJECT','INSERT'),0) AS can_insert,COALESCE(HAS_PERMS_BY_NAME('TEST.'+t.name,'OBJECT','DELETE'),0) AS can_delete
 FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE s.name='TEST' FOR JSON PATH) AS permissions,
 (SELECT t.name AS [table],i.name,i.is_unique,i.has_filter,c.name AS [column],ic.key_ordinal FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.indexes i ON i.object_id=t.object_id JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE s.name='TEST' AND i.is_unique=1 AND ic.key_ordinal>0 AND t.name IN ('ITMMASTER','ITMFACILIT','ITMBPS','ITMSALES','ATEXTRA','BPARTNER','BPSUPPLIER','BPADDRESS','TABUNIT','TABCOEFF') FOR JSON PATH) AS indexes,
 (SELECT t.name AS [table],tr.name,tr.is_disabled FROM sys.triggers tr JOIN sys.tables t ON t.object_id=tr.parent_id JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE s.name='TEST' AND t.name IN ('ITMMASTER','ITMFACILIT','ITMBPS','ITMSALES','ATEXTRA','BPARTNER','BPSUPPLIER','BPADDRESS','TABUNIT','TABCOEFF') FOR JSON PATH) AS triggers,
 (SELECT fk.name,OBJECT_NAME(fk.parent_object_id) AS [table],COL_NAME(fkc.parent_object_id,fkc.parent_column_id) AS [column],OBJECT_NAME(fkc.referenced_object_id) AS referenced_table,COL_NAME(fkc.referenced_object_id,fkc.referenced_column_id) AS referenced_column FROM sys.foreign_keys fk JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id=fk.object_id WHERE OBJECT_SCHEMA_NAME(fk.parent_object_id)='TEST' AND OBJECT_NAME(fk.referenced_object_id) IN ('ITMMASTER','BPSUPPLIER','BPARTNER') FOR JSON PATH) AS foreign_keys
 ,(SELECT CODFIC_0,CODZONE_0,CODTYP_0,LIEN_0,EXPLIEN_0,OPTION_0,ANNUL_0,NOLIB_0 FROM TEST.ATABZON WHERE CODTYP_0 IN ('ITM','BPS','BPR') OR LIEN_0 IN ('ITM','BPS','BPR','ITMMASTER','BPSUPPLIER','BPARTNER') OR (CODFIC_0 IN ('ITMMASTER','ITMFACILIT','PORDER','SORDER','PRECEIPT','SDELIVERY','TABVAT','TABUNIT') AND CODZONE_0 IN ('ITMSTA','CLEFLG','CFMFLG','INVFLG','STOMGTCOD','VACITM','ACCCOD','UOMTYP')) FOR JSON PATH) AS dictionary,
 (SELECT tr.name,OBJECT_DEFINITION(tr.object_id) AS definition FROM sys.triggers tr JOIN sys.tables t ON t.object_id=tr.parent_id WHERE OBJECT_SCHEMA_NAME(t.object_id)='TEST' AND t.name='ITMMASTER' FOR JSON PATH) AS trigger_definitions,
 (SELECT t.name AS [table],c.name AS [column],TYPE_NAME(c.system_type_id) AS [type] FROM sys.tables t JOIN sys.columns c ON c.object_id=t.object_id WHERE OBJECT_SCHEMA_NAME(t.object_id)='TEST' AND t.name IN ('PORDER','PORDERQ','PORDERP','PORDERC','SORDER','SORDERQ','SORDERP','SORDERC','PRECEIPT','PRECEIPTD','PINVOICE','PINVOICED','SDELIVERY','SDELIVERYD','SINVOICE','SINVOICED','STOCK','STOALL','STOJOU','ITMMVT','MFGHEAD','MFGITM') FOR JSON PATH) AS dependency_status_columns,
 (SELECT z.CODFIC_0,z.CODZONE_0,z.NOLIB_0,l.LANNUM_0,l.LANMES_0 FROM TEST.ATABZON z JOIN TEST.APLSTD l ON l.LANCHP_0=z.NOLIB_0 AND l.LAN_0='FRA' WHERE z.CODFIC_0 IN ('PORDER','PORDERQ','SORDER','SORDERQ','PRECEIPT','PINVOICE','SDELIVERY','SINVOICE','MFGHEAD') AND z.CODZONE_0 IN ('CLEFLG','LINCLEFLG','INVFLG','CFMFLG','MFGSTA','STA','DOSTA') FOR JSON PATH) AS status_menus
 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
SELECT @Out;
